require_once __DIR__ . '/../../includes/auth.php';requireLogin();if(!hasRole('admin','gerente','financeiro')){http_response_code(403);die('Acesso restrito.');}$db=getDB();$id=(int)($_GET['id']??0);$v=[];
if($id){$st=$db->prepare('SELECT * FROM contas WHERE id=?');$st->execute([$id]);$v=$st->fetch();if(!$v){header('Location:index.php');exit;}}
$clientes=$db->query("SELECT id,COALESCE(nome,nome_fantasia,razao_social) nome FROM clientes WHERE ativo=1 ORDER BY nome")->fetchAll();$oss=$db->query("SELECT id,numero FROM ordens_servico ORDER BY id DESC LIMIT 300")->fetchAll();
if($_SERVER['REQUEST_METHOD']==='POST'){$d=$_POST;$fields=['ordem_servico_id','cliente_id','tipo','descricao','valor','data_vencimento','data_pagamento','status','forma_pagamento','parcela_atual','total_parcelas','observacoes'];$vals=[];foreach($fields as $f){$vals[$f]=$d[$f]??null;if($vals[$f]==='')$vals[$f]=null;}if($vals['status']==='pago'&&!$vals['data_pagamento'])$vals['data_pagamento']=date('Y-m-d');if($id){$set=implode(',',array_map(fn($f)=>"$f=:$f",array_keys($vals)));$vals['id']=$id;$db->prepare("UPDATE contas SET $set WHERE id=:id")->execute($vals);}else{$cols=implode(',',array_keys($vals));$ph=implode(',',array_map(fn($f)=>":$f",array_keys($vals)));$db->prepare("INSERT INTO contas($cols) VALUES($ph)")->execute($vals);}$_SESSION['msg']=$id?'Lançamento atualizado.':'Lançamento criado.';header('Location:index.php');exit;}require_once __DIR__ . '/../../includes/header.php';
?>
<div class="page-header"><div class="page-title"><i class="fa-solid fa-file-invoice-dollar"></i> <?= $id?'Editar':'Novo' ?> lançamento</div><a class="btn btn-outline" href="index.php">Voltar</a></div><form method="POST"><div class="card"><div class="card-body"><div class="form-row cols-3"><div class="form-group"><label>Tipo *</label><select name="tipo" required><option value="receber" <?= ($v['tipo']??'receber')==='receber'?'selected':'' ?>>Conta a receber</option><option value="pagar" <?= ($v['tipo']??'')==='pagar'?'selected':'' ?>>Conta a pagar</option></select></div><div class="form-group"><label>Descrição *</label><input name="descricao" required value="<?= htmlspecialchars($v['descricao']??'') ?>"></div><div class="form-group"><label>Valor *</label><input type="number" min="0.01" step="0.01" name="valor" required value="<?= htmlspecialchars($v['valor']??'') ?>"></div></div><div class="form-row cols-3"><div class="form-group"><label>Cliente</label><select name="cliente_id"><option value="">Nenhum</option><?php foreach($clientes as $c):?><option value="<?= $c['id'] ?>" <?= ($v['cliente_id']??'')==$c['id']?'selected':'' ?>><?= htmlspecialchars($c['nome']) ?></option><?php endforeach;?></select></div><div class="form-group"><label>Ordem de serviço</label><select name="ordem_servico_id"><option value="">Nenhuma</option><?php foreach($oss as $o):?><option value="<?= $o['id'] ?>" <?= ($v['ordem_servico_id']??'')==$o['id']?'selected':'' ?>><?= htmlspecialchars($o['numero']) ?></option><?php endforeach;?></select></div><div class="form-group"><label>Forma de pagamento</label><select name="forma_pagamento"><option value="">A definir</option><?php foreach(['dinheiro'=>'Dinheiro','pix'=>'PIX','boleto'=>'Boleto','cartao_credito'=>'Cartão de crédito','cartao_debito'=>'Cartão de débito','transferencia'=>'Transferência','cheque'=>'Cheque','outro'=>'Outro'] as $k=>$l):?><option value="<?= $k ?>" <?= ($v['forma_pagamento']??'')===$k?'selected':'' ?>><?= $l ?></option><?php endforeach;?></select></div></div><div class="form-row cols-4"><div class="form-group"><label>Vencimento</label><input type="date" name="data_vencimento" value="<?= htmlspecialchars($v['data_vencimento']??date('Y-m-d')) ?>"></div><div class="form-group"><label>Data do pagamento</label><input type="date" name="data_pagamento" value="<?= htmlspecialchars($v['data_pagamento']??'') ?>"></div><div class="form-group"><label>Situação</label><select name="status"><?php foreach(['pendente'=>'Pendente','pago'=>'Pago','cancelado'=>'Cancelado'] as $k=>$l):?><option value="<?= $k ?>" <?= ($v['status']??'pendente')===$k?'selected':'' ?>><?= $l ?></option><?php endforeach;?></select></div><div class="form-group"><label>Parcela</label><div style="display:flex;gap:6px"><input type="number" min="1" name="parcela_atual" value="<?= (int)($v['parcela_atual']??1) ?>"><input type="number" min="1" name="total_parcelas" value="<?= (int)($v['total_parcelas']??1) ?>"></div></div></div><div class="form-group"><label>Observações</label><textarea name="observacoes" rows="4"><?= htmlspecialchars($v['observacoes']??'') ?></textarea></div></div></div><div class="wizard-actions"><a class="btn btn-outline" href="index.php">Cancelar</a><button class="btn btn-primary"><i class="fa-solid fa-floppy-disk"></i> Salvar</button></div></form><?php require_once __DIR__ . '/../../includes/footer.php'; ?>
